289	bool isUnsaturated(const Atom *atom, const ROMol &mol) {
290	  for (auto bond : mol.atomBonds(atom)) {
291	    // can't just check for single bonds, because dative bonds also have an
292	    // order of 1
293	    if (bond->getBondTypeAsDouble() > 1) {
294	      return true;
295	    }
296	  }
297	  return false;
298	}
