300	bool hasSingleHQuery(const Atom::QUERYATOM_QUERY *q) {
301	  // list queries are series of nested ors of AtomAtomicNum queries
302	  PRECONDITION(q, "bad query");
303	  bool res = false;
304	  const auto &descr = q->getDescription();
305	  if (descr == "AtomAnd") {
306	    for (auto cIt = q->beginChildren(); cIt != q->endChildren(); ++cIt) {
307	      const auto &cDescr = (*cIt)->getDescription();
308	      if (cDescr == "AtomHCount") {
309	        return !(*cIt)->getNegation() &&
310	               ((ATOM_EQUALS_QUERY *)(*cIt).get())->getVal() == 1;
311	      } else if (cDescr == "AtomAnd") {
312	        res = hasSingleHQuery((*cIt).get());
313	        if (res) {
314	          return true;
315	        }
316	      }
317	    }
318	  }
319	  return res;
320	}
