322	bool atomHasFourthValence(const Atom *atom) {
323	  if (atom->getNumExplicitHs() == 1 ||
324	      (!atom->needsUpdatePropertyCache() &&
325	       atom->getValence(Atom::ValenceType::IMPLICIT) == 1)) {
326	    return true;
327	  }
328	  if (atom->hasQuery()) {
329	    // the SMARTS [C@@H] produces an atom with a H query, but we also
330	    // need to treat this like an explicit H for chirality purposes
331	    // This was Github #1489
332	    return hasSingleHQuery(atom->getQuery());
333	  }
334	  return false;
335	}
