468	  // the anchor atom comes before the double bond end atom2 (I think
469	  // this always requires rings to be involved). An example of firstFromAtom2
470	  //  being flipped would be the C atom in "C\N=2" in C=c1s/c2n(c1=O)CCCCC\N=2
471	
472	  bool isFirstFromAtom2Flipped = [&]() {
473	    auto anchorIdx = firstFromAtom2->getOtherAtom(atom2)->getIdx();
474	    return (atomVisitOrders[anchorIdx] < atomVisitOrders[atom2->getIdx()]) !=
475	           firstFromAtom2->hasProp(
476	               common_properties::_TraversalRingClosureBond);
477	  }();
