43	#if ENABLE_EXTRA_CHECKS
44	void checkDirCounts(const ROMol &mol, const std::vector<int8_t> &bondDirCounts,
45	                    const std::vector<int8_t> &atomDirCounts) {
46	  // atoms at the end of double bonds can only have 2 bonds with directions
47	  for (auto atomCount : atomDirCounts) {
48	    if (atomCount < 0 || atomCount > 2) {
49	      throw ValueErrorException(
50	          "inconsistent stereochemistry: atom with more than 2 direction bonds");
51	    }
52	  }
53	
54	  std::vector<int8_t> numDblBondsPerAtom(mol.getNumAtoms(), 0);
55	  for (auto bond : mol.bonds()) {
56	    if (bond->getBondType() == Bond::DOUBLE &&
57	        bond->getStereo() > Bond::STEREOANY) {
58	      for (auto atomIdx : {bond->getBeginAtomIdx(), bond->getEndAtomIdx()}) {
59	        if (atomDirCounts[atomIdx]) {
60	          ++numDblBondsPerAtom[atomIdx];
61	        }
62	      }
63	    }
64	  }
65	
66	  for (auto bond : mol.bonds()) {
67	    // typical value is 2; can be higher in rare cases with directly
68	    // adjacent stereo bonds.
69	    auto maxBondCount = numDblBondsPerAtom[bond->getBeginAtomIdx()] +
70	                        numDblBondsPerAtom[bond->getEndAtomIdx()];
71	    auto bondCount = bondDirCounts[bond->getIdx()];
72	    if (bondCount < 0 || bondCount > maxBondCount) {
73	      throw ValueErrorException(
74	          "inconsistent stereochemistry: bond with more than 2 direction bonds");
75	    }
76	  }
77	}
78	#endif
