92	void setDirectionFromNeighboringBond(const Bond &sourceBond,
93	                                     bool isSourceBondFlipped, Bond &targetBond,
94	                                     bool isTargetBondFlipped) {
95	  auto dir = sourceBond.getBondDir();
96	
97	  // By default, both bonds on the same side of the double bond
98	  // should have opposite directions, but this can change if
99	  // one (and only one) of the bonds is flipped (if both were
100	  // flipped, the flips in the direction would cancel out).
101	  if (isSourceBondFlipped == isTargetBondFlipped) {
102	    dir = flipStereoBondDir(dir);
103	  }
104	
105	  targetBond.setBondDir(dir);
106	}
