108	Bond::BondDir getReferenceDirection(const Bond &dblBond, const Atom &refAtom,
109	                                    const Atom &targetAtom,
110	                                    const Bond &refControllingBond,
111	                                    bool refIsFlipped, const Bond &targetBond,
112	                                    bool targetIsFlipped) {
113	  Bond::BondDir dir = Bond::NONE;
114	  if (dblBond.getStereo() == Bond::STEREOE ||
115	      dblBond.getStereo() == Bond::STEREOTRANS) {
116	    dir = refControllingBond.getBondDir();
117	  } else if (dblBond.getStereo() == Bond::STEREOZ ||
118	             dblBond.getStereo() == Bond::STEREOCIS) {
119	    dir = flipStereoBondDir(refControllingBond.getBondDir());
120	  }
121	  CHECK_INVARIANT(dir != Bond::NONE, "stereo not set");
122	
123	  // If we're not looking at the bonds used to determine the
124	  // stereochemistry, we need to flip the setting on the other bond:
125	  const INT_VECT &stereoAtoms = dblBond.getStereoAtoms();
126	
127	  if (refAtom.getDegree() == 3 &&
128	      std::ranges::find(stereoAtoms,
129	                        static_cast<int>(refControllingBond.getOtherAtomIdx(
130	                            refAtom.getIdx()))) == stereoAtoms.end()) {
131	    dir = flipStereoBondDir(dir);
132	  }
133	  if (targetAtom.getDegree() == 3 &&
134	      std::ranges::find(stereoAtoms,
135	                        static_cast<int>(targetBond.getOtherAtomIdx(
136	                            targetAtom.getIdx()))) == stereoAtoms.end()) {
137	    dir = flipStereoBondDir(dir);
138	  }
139	
140	  // XOR: flips will cancel out if we do both
141	  if (refIsFlipped != targetIsFlipped) {
142	    dir = flipStereoBondDir(dir);
143	  }
144	
145	  return dir;
146	}
