148	bool fixConflictAcrossDoubleBond(const Bond &dblBond, const Atom &atom,
149	                                 const Bond &firstBond, bool firstIsFlipped,
150	                                 const Bond &secondBond, bool secondIsFlipped,
151	                                 const Atom &refAtom, const Bond &refBond,
152	                                 bool refIsFlipped,
153	                                 std::vector<int8_t> &bondDirCounts,
154	                                 std::vector<int8_t> &atomDirCounts) {
155	  for (const auto &[bond, isFlipped] :
156	       {std::make_pair(firstBond, firstIsFlipped),
157	        std::make_pair(secondBond, secondIsFlipped)}) {
158	    auto otherBond = (&bond == &firstBond ? secondBond : firstBond);
159	    auto otherIdx = otherBond.getOtherAtomIdx(atom.getIdx());
160	    auto canOtherDirBeRemoved = atomDirCounts[otherIdx] == 2;
161	
162	    if (!canOtherDirBeRemoved) {
163	      continue;
164	    }
165	
166	    auto expectedAtom2Dir = getReferenceDirection(
167	        dblBond, refAtom, atom, refBond, refIsFlipped, bond, isFlipped);
168	    if (expectedAtom2Dir == bond.getBondDir()) {
169	      bondDirCounts[otherBond.getIdx()] = 0;
170	      --atomDirCounts[atom.getIdx()];
171	      --atomDirCounts[otherIdx];
172	      return true;
173	    }
174	  }
175	  return false;
176	}
