178	bool handleDirConflictsAcrossDoubleBond(
179	    const Bond &dblBond, const Atom &atom1, bool atom1DirsAreConsistent,
180	    const Bond &firstFromAtom1, bool isFirstFromAtom1Flipped,
181	    const Bond &secondFromAtom1, bool isSecondFromAtom1Flipped,
182	    const Atom &atom2, bool atom2DirsAreConsistent, const Bond &firstFromAtom2,
183	    bool isFirstFromAtom2Flipped, const Bond &secondFromAtom2,
184	    bool isSecondFromAtom2Flipped, std::vector<int8_t> &bondDirCounts,
185	    std::vector<int8_t> &atomDirCounts
186	
187	) {
188	  if (atom1DirsAreConsistent && atom2DirsAreConsistent) {
189	    // The directions on each side are consistent, so if they are also
190	    // consistent across the double bond, then all is good. But if they
191	    // are incompatible with the double bond's stereo label there's
192	    // nothing we can do to fix the situation.
193	    auto expectedFirstFromAtom2Dir = getReferenceDirection(
194	        dblBond, atom1, atom2, firstFromAtom1, isFirstFromAtom1Flipped,
195	        firstFromAtom2, isFirstFromAtom2Flipped);
196	    return expectedFirstFromAtom2Dir == firstFromAtom2.getBondDir();
197	
198	  } else if (!atom2DirsAreConsistent && atom1DirsAreConsistent) {
199	    // atom2 has conflicting directions, which means we must have a
200	    // secondFromAtom2. We don't know anything about secondFromAtom1:
201	    // it might be present or not, but we don't care about it, since
202	    // we know it is not problematic.
203	    return fixConflictAcrossDoubleBond(
204	        dblBond, atom2, firstFromAtom2, isFirstFromAtom2Flipped,
205	        secondFromAtom2, isSecondFromAtom2Flipped, atom1, firstFromAtom1,
206	        isFirstFromAtom1Flipped, bondDirCounts, atomDirCounts);
207	
208	  } else if (!atom1DirsAreConsistent && atom2DirsAreConsistent) {
209	    // atom1 has conflicting directions, which means we must have a
210	    // secondFromAtom1. We don't know anything about secondFromAtom2:
211	    // it might be present or not, but we don't care about it, since
212	    // we know it is not problematic.
213	    return fixConflictAcrossDoubleBond(
214	        dblBond, atom1, firstFromAtom1, isFirstFromAtom1Flipped,
215	        secondFromAtom1, isSecondFromAtom1Flipped, atom2, firstFromAtom2,
216	        isFirstFromAtom2Flipped, bondDirCounts, atomDirCounts);
217	
218	  } else {
219	    // This is the tricky one. We have conflicts on both sides,
220	    // which means we must have both secondFromAtom1 and secondFromAtom2.
221	    // We need to check which directions can be removed, and which need
222	    // to be removed to end up with a valid across-double-bond configuration.
223	
224	    for (const auto &[atom1Bond, atom1BondisFlipped] :
225	         {std::make_pair(firstFromAtom1, isFirstFromAtom1Flipped),
226	          std::make_pair(secondFromAtom1, isSecondFromAtom1Flipped)}) {
227	      for (const auto &[atom2Bond, atom2BondisFlipped] :
228	           {std::make_pair(firstFromAtom2, isFirstFromAtom2Flipped),
229	            std::make_pair(secondFromAtom2, isSecondFromAtom2Flipped)}) {
230	        auto expectedAtom2Dir = getReferenceDirection(
231	            dblBond, atom1, atom2, atom1Bond, atom1BondisFlipped, atom2Bond,
232	            atom2BondisFlipped);
233	        if (expectedAtom2Dir == atom2Bond.getBondDir()) {
234	          // We have found a combination of directions that are consistent with
235	          // the double bond's stereo label. Now we need to check if we can
236	          // remove the other two directions to fix the conflict.
237	
238	          auto atom1OtherBond =
239	              (&atom1Bond == &firstFromAtom1 ? secondFromAtom1
240	                                             : firstFromAtom1);
241	          auto atom1OtherIdx = atom1OtherBond.getOtherAtomIdx(atom1.getIdx());
242	          auto canAtom1OtherDirBeRemoved = atomDirCounts[atom1OtherIdx] == 2;
243	          if (!canAtom1OtherDirBeRemoved) {
244	            continue;
245	          }
246	
247	          auto atom2OtherBond =
248	              (&atom2Bond == &firstFromAtom2 ? secondFromAtom2
249	                                             : firstFromAtom2);
250	          auto atom2OtherIdx = atom2OtherBond.getOtherAtomIdx(atom2.getIdx());
251	          if (atom1OtherIdx == atom2OtherIdx) {
252	            // unlikely, but not impossible, so just in case...
253	            continue;
254	          }
255	
256	          auto canAtom2OtherDirBeRemoved = atomDirCounts[atom2OtherIdx] == 2;
257	          if (!canAtom2OtherDirBeRemoved) {
258	            continue;
259	          }
260	
261	          bondDirCounts[atom1OtherBond.getIdx()] = 0;
262	          --atomDirCounts[atom1.getIdx()];
263	          --atomDirCounts[atom1OtherIdx];
264	
265	          bondDirCounts[atom2OtherBond.getIdx()] = 0;
266	          --atomDirCounts[atom2.getIdx()];
267	          --atomDirCounts[atom2OtherIdx];
268	
269	          return true;
270	        }
271	      }
272	    }
273	  }
274	
275	  return false;
276	}
