3457	void finishMolProcessing(
3458	    RWMol *res, bool chiralityPossible,
3459	    const RDKit::v2::FileParsers::MolFileParserParams &params) {
3460	  if (!res) {
3461	    return;
3462	  }
3463	  res->clearAllAtomBookmarks();
3464	  res->clearAllBondBookmarks();
3465	
3466	  if (params.expandAttachmentPoints) {
3467	    MolOps::expandAttachmentPoints(*res);
3468	  }
3469	
3470	  // calculate explicit valence on each atom:
3471	  for (auto atom : res->atoms()) {
3472	    atom->calcExplicitValence(false);
3473	  }
3474	
3475	  // postprocess mol file flags
3476	  ProcessMolProps(res);
3477	
3478	  // update the chirality and stereo-chemistry
3479	  //
3480	  // NOTE: we detect the stereochemistry before sanitizing/removing
3481	  // hydrogens because the removal of H atoms may actually remove
3482	  // the wedged bond from the molecule.  This wipes out the only
3483	  // sign that chirality ever existed and makes us sad... so first
3484	  // perceive chirality, then remove the Hs and sanitize.
3485	  //
3486	  const Conformer &conf = res->getConformer();
3487	  if (chiralityPossible || conf.is3D()) {
3488	    if (!conf.is3D()) {
3489	      bool replaceExistingTags = true;
3490	      MolOps::assignChiralTypesFromBondDirs(*res, conf.getId(),
3491	                                            replaceExistingTags);
3492	    } else {
3493	      res->updatePropertyCache(false);
3494	      MolOps::assignChiralTypesFrom3D(*res, conf.getId(), true);
3495	    }
3496	  }
3497	
3498	  Atropisomers::detectAtropisomerChirality(*res, &conf);
3499	
3500	  // now that atom stereochem has been perceived, the wedging
3501	  // information is no longer needed, so we clear
3502	  // single bond dir flags:
3503	  MolOps::clearSingleBondDirFlags(*res);
3504	
3505	  if (params.sanitize) {
3506	    if (params.removeHs) {
3507	      // Bond stereo detection must happen before H removal, or
3508	      // else we might be removing stereogenic H atoms in double
3509	      // bonds (e.g. imines). But before we run stereo detection,
3510	      // we need to run mol cleanup so don't have trouble with
3511	      // e.g. nitro groups. Sadly, this a;; means we will find
3512	      // run both cleanup and ring finding twice (a fast find
3513	      // rings in bond stereo detection, and another in
3514	      // sanitization's SSSR symmetrization).
3515	      unsigned int failedOp = 0;
3516	      MolOps::sanitizeMol(*res, failedOp, MolOps::SANITIZE_CLEANUP);
3517	      MolOps::detectBondStereochemistry(*res);
3518	      MolOps::removeHs(*res);
3519	    } else {
3520	      MolOps::sanitizeMol(*res);
3521	      MolOps::detectBondStereochemistry(*res);
3522	    }
3523	
3524	    MolOps::assignStereochemistry(*res, true, true, true);
3525	  } else {
3526	    MolOps::detectBondStereochemistry(*res);
3527	  }
3528	
3529	  if (res->hasProp(common_properties::_NeedsQueryScan)) {
