113	Bond::BondDir getBondDirForAtropisomerNoConf(Bond::BondStereo bondStereo,
114	                                             unsigned int whichEnd,
115	                                             unsigned int whichBond) {
116	  // the convention is that in the absence of coords, the coordiates are choosen
117	  // with the lowest numbered atom of the atrop bond down, and the other atom
118	  // straight up.
119	  // On each end, the lowest numbered connecting atom is on the left
120	  //
121	  //              a      b
122	  //               \   /
123	  //                 c
124	  //                 |
125	  //                 d
126	  //               /   \     aaa
127	  //              e      f
128	  //
129	  // where  c > d
130	  //        a < b
131	  //        e < f
132	
133	  PRECONDITION(whichEnd <= 1, "whichEnd must be 0 or 1");
134	  PRECONDITION(whichBond <= 1, "whichBond must be 0 or 1");
135	  PRECONDITION(bondStereo == Bond::BondStereo::STEREOATROPCW ||
136	                   bondStereo == Bond::BondStereo::STEREOATROPCCW,
137	               "bondStereo must be BondAtropisomerCW or BondAtropisomerCCW");
138	
139	  int flips = 0;
140	  if (bondStereo == Bond::BondStereo::STEREOATROPCW) {
141	    ++flips;
142	  }
143	  if (whichBond == 1) {
144	    ++flips;
145	  }
146	  if (whichEnd == 1) {
147	    ++flips;
148	  }
149	
150	  return flips % 2 ? Bond::BEGINDASH : Bond::BEGINWEDGE;
151	}
152	
153	Bond::BondDir getBondDirForAtropisomer2d(RDGeom::Point3D bondVecs[2],
154	                                         Bond::BondStereo bondStereo,
155	                                         unsigned int whichEnd,
156	                                         unsigned int whichBond) {
157	  PRECONDITION(whichEnd <= 1, "whichEnd must be 0 or 1");
158	  PRECONDITION(whichBond <= 1, "whichBond must be 0 or 1");
159	  PRECONDITION(bondStereo == Bond::BondStereo::STEREOATROPCW ||
160	                   bondStereo == Bond::BondStereo::STEREOATROPCCW,
161	               "bondStereo must be BondAtropisomerCW or BondAtropisomerCCW");
162	
163	  int flips = 0;
164	  if (bondStereo == Bond::BondStereo::STEREOATROPCCW) {
165	    ++flips;
166	  }
167	  if (whichBond == 1) {
168	    ++flips;
169	  }
170	  if (whichEnd == 1) {
171	    ++flips;
172	  }
173	  if (bondVecs[1 - whichEnd].y < 0) {
174	    ++flips;  // if the OTHER end is negative for the low index bond vec, it
175	              // is a flip
176	  }
177	
178	  return flips % 2 ? Bond::BEGINWEDGE : Bond::BEGINDASH;
179	}
180	
181	Bond::BondDir getBondDirForAtropisomer3d(Bond *whichBond,
182	                                         const Conformer *conf) {
183	  // for 3D we mark it as wedge or hash depending on the z-value of the bond
184	  // vector
185	  //  IT really doesn't matter since we ignore these except as MARKERS for
186	  //  which bonds are atropisomer bonds
187	  if ((conf->getAtomPos(whichBond->getEndAtom()->getIdx()).z -
188	       conf->getAtomPos(whichBond->getBeginAtom()->getIdx()).z) >
189	      REALLY_SMALL_BOND_LEN) {
190	    return Bond::BondDir::BEGINWEDGE;
191	  } else {
192	    return Bond::BondDir::BEGINDASH;
193	  }
194	}
195	
196	bool getAtropIsomerEndVect(const AtropAtomAndBondVec &atomAndBondVec,
197	                           const RDGeom::Point3D &yAxis,
198	                           const RDGeom::Point3D &zAxis, const Conformer *conf,
199	                           RDGeom::Point3D &bondVec) {
200	  PRECONDITION(
201	      atomAndBondVec.second.size() > 0 && atomAndBondVec.second.size() < 3,
202	      "bad bond size");
203	  PRECONDITION(atomAndBondVec.second[0], "bad first bond");
204	  PRECONDITION(atomAndBondVec.second.size() == 1 || atomAndBondVec.second[1],
205	               "bad second bond");
206	
207	  bondVec = conf->getAtomPos(atomAndBondVec.second[0]
208	                                 ->getOtherAtom(atomAndBondVec.first)
209	                                 ->getIdx()) -
210	            conf->getAtomPos(
211	                atomAndBondVec.first->getIdx());  // in old frame of reference
212	
213	  bondVec = RDGeom::Point3D(0.0, bondVec.dotProduct(yAxis),
214	                            bondVec.dotProduct(zAxis));  // in new frame
215	
216	  // make sure the other atom is on the other side
217	
218	  if (atomAndBondVec.second.size() == 2) {
219	    RDGeom::Point3D otherVec =
220	        conf->getAtomPos(atomAndBondVec.second[1]
221	                             ->getOtherAtom(atomAndBondVec.first)
222	                             ->getIdx()) -
223	        conf->getAtomPos(
224	            atomAndBondVec.first->getIdx());  // in old frame of reference
225	    otherVec = RDGeom::Point3D(0.0, otherVec.dotProduct(yAxis),
226	                               otherVec.dotProduct(zAxis));  // in new frame
227	
228	    if (bondVec.length() < REALLY_SMALL_BOND_LEN) {
229	      bondVec = -otherVec;  // put it on the other side of otherVec
230	    } else if (bondVec.dotProduct(otherVec) > REALLY_SMALL_BOND_LEN) {
231	      // the product of dotproducts (y-values) should be
232	      // negative (or at least zero)
233	      BOOST_LOG(rdWarningLog)
234	          << "Both bonds on one end of an atropisomer are on the same side - atoms is : "
235	          << atomAndBondVec.first->getIdx() << std::endl;
236	      return false;
237	    }
238	  }
239	  if (bondVec.length() < REALLY_SMALL_BOND_LEN) {
240	    BOOST_LOG(rdWarningLog)
241	        << "Could not find a bond on one end of an atropisomer that is not co-linear - atoms are : "
242	        << atomAndBondVec.first->getIdx() << std::endl;
243	    return false;
244	  }
245	
246	  bondVec.normalize();
247	  return true;
248	}
249	
250	std::pair<bool, Bond::BondDir> getBondDir(
251	    const Bond *bond, const AtropAtomAndBondVec &atomAndBondVec) {
252	  // get the wedge dir for this end of the bond
253	  // if the first bond 1 has a bondDir, use it
254	  // if the second bond has a bond dir use the opposite of if
255	  // if both bonds have a dir, make sure they are different
256	
257	  auto bond1Dir = atomAndBondVec.second[0]->getBondDir();
258	  if (bond1Dir != Bond::BEGINWEDGE && bond1Dir != Bond::BEGINDASH) {
259	    bond1Dir = Bond::NONE;  //  we dont care if it any thing else
260	  }
261	  auto bond2Dir = atomAndBondVec.second.size() == 2
262	                      ? atomAndBondVec.second[1]->getBondDir()
263	                      : Bond::NONE;
264	  if (bond2Dir != Bond::BEGINWEDGE && bond2Dir != Bond::BEGINDASH) {
265	    bond2Dir = Bond::NONE;
266	  }
267	
268	  // if both are set to a direction, they must NOT be the same - one
269	  // must be a dash and the other a hash
270	
271	  if (bond1Dir != Bond::NONE && bond2Dir != Bond::NONE &&
272	      bond1Dir == bond2Dir) {
273	    BOOST_LOG(rdWarningLog)
274	        << "The bonds on one end of an atropisomer are both UP or both DOWN - atoms are: "
275	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
276	    return {false, Bond::BondDir::NONE};
277	  }
278	
279	  if (bond1Dir == Bond::BEGINWEDGE || bond2Dir == Bond::BEGINDASH) {
280	    return {true, Bond::BondDir::BEGINWEDGE};
281	  }
282	  if (bond1Dir == Bond::BEGINDASH || bond2Dir == Bond::BEGINWEDGE) {
283	    return {true, Bond::BondDir::BEGINDASH};
284	  }
285	  return {true, Bond::BondDir::NONE};
286	}
