288	void DetectAtropisomerChiralityOneBond(Bond *bond, ROMol &mol,
289	                                       const Conformer *conf) {
290	  // the approach is this:
291	  // we will view the system along the line from the potential atropisomer
292	  // bond, from atom1 to atom 2 and we do a coordinate transformation to
293	  // the plane of reference where that vector, from a1 to a2, is the x-AXIS.
294	  // For 2D, the y axis is in the 2D plane, and the zaxis is perpendicaul to
295	  // the 2D plane For 3D, the Y and Z axes are taken arbitrarily to form
296	  // a right-handed system with the X-axis.
297	  //  atoms 1 and 2 each have one or two bonds out from the main potential
298	  //  atrop bond. for each end of the main bond, we find a vector to reprent
299	  //  the neighbor atom with the smallest index as its projection onto the
300	  //  x=0 plane.
301	  // (In 2d, this projection is on the y-AXIS for the end that does NOT have
302	  // a wedge/hash bond, and  on the z axis - out of the plane - for the end
303	  // that does have a wedge/hash). The chirality is recorded as the
304	  // direction we rotate from, atom 1's projection to atom2's proejection -
305	  // either clockwise or counter clockwise
306	
307	  PRECONDITION(bond, "bad bond");
308	
309	  // one vector for each end - each one - should end up with 1 or 2 entries
310	  AtropAtomAndBondVec atomAndBondVecs[2];
311	  if (!getAtropisomerAtomsAndBonds(bond, atomAndBondVecs, mol)) {
312	    return;  // not an atropisomer
313	  }
314	
315	  // make sure we do not have wiggle bonds
316	
317	  for (auto atomAndBondVec : atomAndBondVecs) {
318	    for (auto endBond : atomAndBondVec.second) {
319	      if (endBond->getBondDir() == Bond::UNKNOWN) {
320	        return;  // not an atropisomer
321	      }
322	    }
323	  }
324	
325	  // the convention is that in the absence of coords, the coordiates are choosen
326	  // with the lowest numbered atom of the atrop bond down, and the other atom
327	  // straight up.
328	  // On each end, the lowest numbered connecting atom is on the left
329	  //
330	  //              a      b
331	  //               \   /
332	  //                 c
333	  //                 |
334	  //                 d
335	  //               /   \     aaa
336	  //              e      f
337	  //
338	  // where  c > d
339	  //        a < b
340	  //        e < f
341	
342	  if (conf == nullptr) {
343	    std::pair<bool, Bond::BondDir> bond1DirResult;
344	    bond1DirResult = getBondDir(bond, atomAndBondVecs[0]);
345	    if (!bond1DirResult.first) {
346	      return;
347	    }
348	    std::pair<bool, Bond::BondDir> bond2DirResult;
349	    bond2DirResult = getBondDir(bond, atomAndBondVecs[1]);
350	    if (!bond2DirResult.first) {
351	      return;
352	    }
353	    if (bond1DirResult.second == bond2DirResult.second) {
354	      BOOST_LOG(rdWarningLog)
355	          << "inconsistent bond wedging for an atropisomer.  Atoms are: "
356	          << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
357	          << std::endl;
358	      return;
359	    }
360	
361	    if (bond1DirResult.second == Bond::BEGINWEDGE ||
362	        bond2DirResult.second == Bond::BEGINDASH) {
363	      bond->setStereo(Bond::BondStereo::STEREOATROPCCW);
364	    } else if (bond1DirResult.second == Bond::BEGINDASH ||
365	               bond2DirResult.second == Bond::BEGINWEDGE) {
366	      bond->setStereo(Bond::BondStereo::STEREOATROPCW);
367	    }
368	
369	    return;
370	  }
371	
372	  // create a frame of reference that has its X-axis along the atrop bond
373	
374	  RDGeom::Point3D xAxis, yAxis, zAxis;
375	  if (!getBondFrameOfReference(bond, conf, xAxis, yAxis, zAxis)) {
376	    // connot percieve atroisomer
377	    BOOST_LOG(rdWarningLog)
378	        << "Failed to get a frame of reference along an atropisomer bond - atoms are: "
379	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
380	    return;
381	  }
382	  RDGeom::Point3D bondVecs[2];  // one bond vector from each end of the
383	                                // potential atropisomer bond
384	
385	  for (int bondAtomIndex = 0; bondAtomIndex < 2; ++bondAtomIndex) {
386	    // if the conf is 2D, we use the wedge bonds to set the coords for the
387	    // projected vector onto the xAxis perpendicular plane (looking down
388	    // the atrop bond )
389	
390	    if (!conf->is3D()) {
391	      // get the wedge dir for this end of the bond
392	      // if the first bond 1 has a bondDir, use it
393	      // if the second bond has a bond dir use the opposite of if
394	      // if both bonds have a dir, make sure they are different
395	
396	      std::pair<bool, Bond::BondDir> bondDirResult;
397	
398	      bondDirResult = getBondDir(bond, atomAndBondVecs[bondAtomIndex]);
399	      if (!bondDirResult.first) {
400	        return;
401	      }
402	
403	      if (!getAtropIsomerEndVect(atomAndBondVecs[bondAtomIndex], yAxis, zAxis,
404	                                 conf, bondVecs[bondAtomIndex])) {
405	        return;
406	      }
407	
408	      if (bondDirResult.second == Bond::BEGINWEDGE) {
409	        bondVecs[bondAtomIndex].y *= 0.707;
410	        bondVecs[bondAtomIndex].z = fabs(bondVecs[bondAtomIndex].y);
411	      } else if (bondDirResult.second == Bond::BEGINDASH) {
412	        bondVecs[bondAtomIndex].y *= 0.707;
413	        bondVecs[bondAtomIndex].z = -fabs(bondVecs[bondAtomIndex].y);
414	      }
415	    } else {  // the conf is 3D
416	      // to be considered, one or more neighbor bonds must have a wedge or
417	      // hash
418	
419	      // find the projection of the bond(s) on this end in the frame of
420	      // reference's  x=0  plane
421	      RDGeom::Point3D tempBondVec =
422	          conf->getAtomPos(
423	              atomAndBondVecs[bondAtomIndex]
424	                  .second[0]
425	                  ->getOtherAtom(atomAndBondVecs[bondAtomIndex].first)
426	                  ->getIdx()) -
427	          conf->getAtomPos(atomAndBondVecs[bondAtomIndex].first->getIdx());
428	      bondVecs[bondAtomIndex] = RDGeom::Point3D(
429	          0.0, tempBondVec.dotProduct(yAxis), tempBondVec.dotProduct(zAxis));
430	
431	      if (atomAndBondVecs[bondAtomIndex].second.size() == 2) {
432	        tempBondVec =
433	            conf->getAtomPos(
434	                atomAndBondVecs[bondAtomIndex]
435	                    .second[1]
436	                    ->getOtherAtom(atomAndBondVecs[bondAtomIndex].first)
437	                    ->getIdx()) -
438	            conf->getAtomPos(atomAndBondVecs[bondAtomIndex].first->getIdx());
439	
440	        // get the projection of the 2nd bond on the x=0 plane
441	
442	        RDGeom::Point3D otherBondVec = RDGeom::Point3D(
443	            0.0, tempBondVec.dotProduct(yAxis), tempBondVec.dotProduct(zAxis));
444	
445	        // if the first atom is co-linear with the main atrop bond, use
446	        // the opposite of the 2nd atom
447	
448	        if (bondVecs[bondAtomIndex].length() < REALLY_SMALL_BOND_LEN) {
449	          bondVecs[bondAtomIndex] =
450	              -otherBondVec;  // note - it might still be co-linear-
451	                              // this is checked below
452	        } else if (bondVecs[bondAtomIndex].dotProduct(otherBondVec) >
453	                   REALLY_SMALL_BOND_LEN) {
454	          BOOST_LOG(rdWarningLog)
455	              << "Both bonds on one end of an atropisomer are on the same side - atoms are: "
456	              << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
457	              << std::endl;
458	          return;
459	        }
460	      }
461	
462	      if (bondVecs[bondAtomIndex].length() < REALLY_SMALL_BOND_LEN) {
463	        BOOST_LOG(rdWarningLog)
464	            << "Failed to find a bond on one end of an atropisomer that is NOT co-linear - atoms are: "
465	            << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
466	            << std::endl;
467	        return;
468	      }
469	    }
470	  }
471	
472	  auto crossProduct = bondVecs[1].crossProduct(bondVecs[0]);
473	
474	  if (crossProduct.x > REALLY_SMALL_BOND_LEN) {
475	    bond->setStereo(Bond::BondStereo::STEREOATROPCCW);
476	  } else if (crossProduct.x < -REALLY_SMALL_BOND_LEN) {
477	    bond->setStereo(Bond::BondStereo::STEREOATROPCW);
478	  } else {
479	    BOOST_LOG(rdWarningLog)
480	        << "The 2 defining bonds for an atropisomer are co-planar - atoms are: "
481	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
482	    return;
483	  }
484	}
