521	void detectAtropisomerChirality(ROMol &mol, const Conformer *conf) {
522	  PRECONDITION(conf == nullptr || &(conf->getOwningMol()) == &mol,
523	               "conformer does not belong to molecule");
524	
525	  std::set<Bond *> bondsToTry;
526	
527	  for (auto bond : mol.bonds()) {
528	    if (canHaveDirection(*bond) &&
529	        (bond->getBondDir() == Bond::BondDir::BEGINDASH ||
530	         bond->getBondDir() == Bond::BondDir::BEGINWEDGE)) {
531	      for (const auto &nbrBond : mol.atomBonds(bond->getBeginAtom())) {
532	        if (nbrBond == bond) {
533	          continue;  // a bond is NOT its own neighbor
534	        }
535	        bondsToTry.insert(nbrBond);
536	      }
537	    }
538	  }
539	
540	  if (bondsToTry.empty()) {
541	    return;
542	  }
543	
544	  // First, do a simple check with TotalDegree to see if any bonds might be
545	  // candidates before doing the expensive hybridization calculation.
546	  bool anyBondPassesDegreeCheck = false;
547	  for (auto bondToTry : bondsToTry) {
548	    if (bondToTry->getBeginAtom()->needsUpdatePropertyCache()) {
549	      bondToTry->getBeginAtom()->updatePropertyCache(false);
550	    }
551	    if (bondToTry->getEndAtom()->needsUpdatePropertyCache()) {
552	      bondToTry->getEndAtom()->updatePropertyCache(false);
553	    }
554	
555	    if (bondToTry->getBondType() == Bond::SINGLE &&
556	        bondToTry->getStereo() != Bond::BondStereo::STEREOANY &&
557	        bondToTry->getBeginAtom()->getTotalDegree() >= 2 &&
558	        bondToTry->getBeginAtom()->getTotalDegree() <= 3 &&
559	        bondToTry->getEndAtom()->getTotalDegree() >= 2 &&
560	        bondToTry->getEndAtom()->getTotalDegree() <= 3) {
561	      anyBondPassesDegreeCheck = true;
562	      break;
563	    }
564	  }
565	
566	  if (!anyBondPassesDegreeCheck) {
567	    return;
568	  }
569	
570	  // defer cache update on the whole mol unless we actually have bonds to try
571	  // we need to do an update on the whole mol and not just incident atoms
572	  // because we need to calculate hybridization, which is non-local
573	  bool needsUpdate =
574	      mol.needsUpdatePropertyCache() ||
575	      std::any_of(mol.atoms().begin(), mol.atoms().end(), [](const auto atom) {
576	        return atom->getAtomicNum() != 0 &&
577	               atom->getHybridization() == Atom::HybridizationType::UNSPECIFIED;
578	      });
579	  if (needsUpdate) {
580	    mol.updatePropertyCache(false);
581	    MolOps::setConjugation(mol);
582	    MolOps::setHybridization(mol);
583	  }
584	
585	  for (auto bondToTry : bondsToTry) {
586	    if (bondToTry->getBondType() != Bond::SINGLE ||
587	        bondToTry->getStereo() == Bond::BondStereo::STEREOANY ||
588	        // before, we checked only on totalDegree = 2 or 3,
589	        // but this causes false positives for something like a chiral sulfoxide
590	        // since the S is tetrahedral (sp3) but has only 3 substituents.
591	        // the hybridization code relies on totalDegree,
592	        // but modified to include and making sure to include conjugation
593	        // so while this is more expensive per molecule, it is closer to intent
594	        bondToTry->getBeginAtom()->getHybridization() != Atom::SP2 ||
595	        bondToTry->getEndAtom()->getHybridization() != Atom::SP2) {
596	      continue;
597	    }
598	
599	    DetectAtropisomerChiralityOneBond(bondToTry, mol, conf);
600	  }
