637	bool WedgeBondFromAtropisomerOneBondNoConf(
638	    Bond *bond, const ROMol &mol,
639	    std::map<int, std::unique_ptr<RDKit::Chirality::WedgeInfoBase>>
640	        &wedgeBonds) {
641	  PRECONDITION(bond, "no bond");
642	
643	  AtropAtomAndBondVec atomAndBondVecs[2];
644	  if (!getAtropisomerAtomsAndBonds(bond, atomAndBondVecs, mol)) {
645	    return false;  // not an atropisomer
646	  }
647	
648	  //  make sure we do not have wiggle bonds
649	
650	  for (auto atomAndBondVec : atomAndBondVecs) {
651	    for (auto endBond : atomAndBondVec.second) {
652	      if (endBond->getBondDir() == Bond::UNKNOWN) {
653	        return false;  // not an atropisomer)
654	      }
655	    }
656	  }
657	
658	  // first see if any candidate bond is already set to a wedge or hash
659	  // if so, we will use that bond as a wedge or hash
660	
661	  std::vector<int> useBondsAtEnd[2];
662	  bool foundBondDir = false;
663	
664	  for (unsigned int whichEnd = 0; whichEnd < 2; ++whichEnd) {
665	    for (unsigned int whichBond = 0;
666	         whichBond < atomAndBondVecs[whichEnd].second.size(); ++whichBond) {
667	      auto bondDir = atomAndBondVecs[whichEnd].second[whichBond]->getBondDir();
668	
669	      // see if it is a wedge or hash and its origin is the atom in the
670	      // main bond
671	
672	      if ((bondDir == Bond::BEGINWEDGE || bondDir == Bond::BEGINDASH) &&
673	          atomAndBondVecs[whichEnd].second[whichBond]->getBeginAtom() ==
674	              atomAndBondVecs[whichEnd].first &&
675	          canHaveDirection(*bond)) {
676	        useBondsAtEnd[whichEnd].push_back(whichBond);
677	        foundBondDir = true;
678	      }
679	    }
680	  }
681	
682	  if (foundBondDir) {
683	    for (unsigned int whichEnd = 0; whichEnd < 2; ++whichEnd) {
684	      for (unsigned int whichBondIndex = 0;
685	           whichBondIndex < useBondsAtEnd[whichEnd].size(); ++whichBondIndex) {
686	        atomAndBondVecs[whichEnd]
687	            .second[useBondsAtEnd[whichEnd][whichBondIndex]]
688	            ->setBondDir(getBondDirForAtropisomerNoConf(
689	                bond->getStereo(), whichEnd,
690	                useBondsAtEnd[whichEnd][whichBondIndex]));
691	      }
692	    }
693	
694	    return true;
695	  }
696	
697	  // did not find a good bond dir - pick one to use
698	  // we would like to have one that is not in a ring, and will be a wedge
699	
700	  const RingInfo *ri = bond->getOwningMol().getRingInfo();
701	
702	  int bestBondEnd = -1, bestBondNumber = -1;
703	  bool bestBondIsSingle = false;
704	  unsigned int bestRingCount = INT_MAX;
705	  Bond::BondDir bestBondDir = Bond::BondDir::NONE;
706	  for (unsigned int whichEnd = 0; whichEnd < 2; ++whichEnd) {
707	    for (unsigned int whichBond = 0;
708	         whichBond < atomAndBondVecs[whichEnd].second.size(); ++whichBond) {
709	      auto bondToTry = atomAndBondVecs[whichEnd].second[whichBond];
710	
711	      if (!canHaveDirection(*bondToTry) ||
712	          wedgeBonds.find(bondToTry->getIdx()) != wedgeBonds.end()) {
713	        continue;  // must be a single OR aromatic bond and not already
714	                   // spoken for by a chiral center
715	      }
716	
717	      if (bondToTry->getBondDir() != Bond::BondDir::NONE) {
718	        if (bondToTry->getBeginAtom()->getIdx() ==
719	            atomAndBondVecs[whichEnd].first->getIdx()) {
720	          BOOST_LOG(rdWarningLog)
721	              << "Wedge or hash bond found on atropisomer where not expected - atoms are: "
722	              << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
723	              << std::endl;
724	          return false;
725	        } else {
726	          continue;  // wedge or hash bond affecting the OTHER atom
727	                     // = perhaps a chiral center
728	        }
729	      }
730	      auto ringCount = ri->numBondRings(bondToTry->getIdx());
731	      if (ringCount > bestRingCount) {
732	        continue;
733	      }
734	
735	      else if (ringCount < bestRingCount) {
736	        bestBondEnd = whichEnd;
737	        bestBondNumber = whichBond;
738	        bestRingCount = ringCount;
739	        bestBondIsSingle = (bondToTry->getBondType() == Bond::BondType::SINGLE);
740	        bestBondDir = getBondDirForAtropisomerNoConf(bond->getStereo(),
741	                                                     whichEnd, whichBond);
742	      } else if (bestBondIsSingle &&
743	                 bondToTry->getBondType() != Bond::BondType::SINGLE) {
744	        continue;
745	
746	      } else if (!bestBondIsSingle &&
747	                 bondToTry->getBondType() == Bond::BondType::SINGLE) {
748	        bestBondEnd = whichEnd;
749	        bestBondNumber = whichBond;
750	        bestRingCount = ringCount;
751	        bestBondIsSingle = true;
752	        bestBondDir = getBondDirForAtropisomerNoConf(bond->getStereo(),
753	                                                     whichEnd, whichBond);
754	
755	      } else {
756	        auto bondDir = getBondDirForAtropisomerNoConf(bond->getStereo(),
757	                                                      whichEnd, whichBond);
758	        if (bestBondDir == Bond::BondDir::NONE ||
759	            (bestBondDir == Bond::BondDir::BEGINDASH &&
760	             bondDir == Bond::BondDir::BEGINWEDGE)) {
761	          bestBondEnd = whichEnd;
762	          bestBondNumber = whichBond;
763	          bestRingCount = ringCount;
764	          bestBondIsSingle =
765	              (bondToTry->getBondType() == Bond::BondType::SINGLE);
766	          bestBondDir = bondDir;
767	        }
768	      }
769	    }
770	  }
771	
772	  if (bestBondEnd >= 0)  // we found a good one
773	  {
774	    // make sure the atoms on the bond are in the right order for the
775	    // wedge/hash the atom on the end of the main bond must be listed
776	    // first for the wedge/has bond
777	
778	    auto bestBond = atomAndBondVecs[bestBondEnd].second[bestBondNumber];
779	    if (bestBond->getBeginAtom() != atomAndBondVecs[bestBondEnd].first) {
780	      bestBond->setEndAtom(bestBond->getBeginAtom());
781	      bestBond->setBeginAtom(atomAndBondVecs[bestBondEnd].first);
782	    }
783	
784	    bestBond->setBondDir(bestBondDir);
785	
786	    auto newWedgeInfo = std::unique_ptr<RDKit::Chirality::WedgeInfoBase>(
787	        new RDKit::Chirality::WedgeInfoAtropisomer(bond->getIdx(),
788	                                                   bestBondDir));
789	    wedgeBonds[bestBond->getIdx()] = std::move(newWedgeInfo);
790	  } else {
791	    BOOST_LOG(rdWarningLog)
792	        << "Failed to find a good bond to set as UP or DOWN for an atropisomer - atoms are: "
793	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
794	    return false;
795	  }
796	
797	  return true;
798	}
