848	      // did not find a non-colinear bond
849	
850	      BOOST_LOG(rdWarningLog)
851	          << "Failed to get a representative vector for the defining bond of an atropisomer - atoms are: "
852	          << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
853	          << std::endl;
854	      return false;
855	    }
856	  }
857	
858	  // first see if any candidate bond is already set to a wedge or hash
859	  // if so, we will use that bond as a wedge or hash
860	
861	  std::vector<int> useBondsAtEnd[2];
862	  bool foundBondDir = false;
863	
864	  for (unsigned int whichEnd = 0; whichEnd < 2; ++whichEnd) {
865	    for (unsigned int whichBond = 0;
866	         whichBond < atomAndBondVecs[whichEnd].second.size(); ++whichBond) {
867	      auto bondDir = atomAndBondVecs[whichEnd].second[whichBond]->getBondDir();
868	
869	      // see if it is a wedge or hash and its origin is the atom in the
870	      // main bond
871	
872	      if ((bondDir == Bond::BEGINWEDGE || bondDir == Bond::BEGINDASH) &&
873	          atomAndBondVecs[whichEnd].second[whichBond]->getBeginAtom() ==
874	              atomAndBondVecs[whichEnd].first &&
875	          canHaveDirection(*bond)) {
