877	        foundBondDir = true;
878	      }
879	    }
880	  }
881	
882	  if (foundBondDir) {
883	    for (unsigned int whichEnd = 0; whichEnd < 2; ++whichEnd) {
884	      for (unsigned int whichBondIndex = 0;
885	           whichBondIndex < useBondsAtEnd[whichEnd].size(); ++whichBondIndex) {
886	        atomAndBondVecs[whichEnd]
887	            .second[useBondsAtEnd[whichEnd][whichBondIndex]]
