906	
907	  int bestBondEnd = -1, bestBondNumber = -1;
908	  bool bestBondIsSingle = false;
909	  unsigned int bestRingCount = INT_MAX;
910	  unsigned int largestRingSize = 0;
911	  Bond::BondDir bestBondDir = Bond::BondDir::NONE;
912	  for (unsigned int whichEnd = 0; whichEnd < 2; ++whichEnd) {
913	    for (unsigned int whichBond = 0;
914	         whichBond < atomAndBondVecs[whichEnd].second.size(); ++whichBond) {
915	      auto bondToTry = atomAndBondVecs[whichEnd].second[whichBond];
916	
917	      if (!canHaveDirection(*bondToTry) ||
918	          wedgeBonds.find(bondToTry->getIdx()) != wedgeBonds.end()) {
919	        continue;  // must be a single OR aromatic bond and not already
920	                   // spoken for by a chiral center
921	      }
922	
923	      if (bondToTry->getBondDir() != Bond::BondDir::NONE) {
924	        if (bondToTry->getBeginAtom()->getIdx() ==
925	            atomAndBondVecs[whichEnd].first->getIdx()) {
926	          if (bondToTry->getBondDir() == Bond::BEGINWEDGE ||
927	              bondToTry->getBondDir() == Bond::BEGINDASH) {
928	            BOOST_LOG(rdWarningLog)
929	                << "Wedge or hash bond found on atropisomer where not expected - atoms are: "
930	                << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
931	                << std::endl;
