987	          bestBondDir = bondDir;
988	        }
989	      }
990	    }
991	  }
992	
993	  if (bestBondEnd >= 0) {
994	    // we found a good one
995	    // make sure the atoms on the bond are in the right order for the
996	    // wedge/hash the atom on the end of the main bond must be listed
997	    // first for the wedge/has bond
998	
999	    auto bestBond = atomAndBondVecs[bestBondEnd].second[bestBondNumber];
1000	    if (bestBond->getBeginAtom() != atomAndBondVecs[bestBondEnd].first) {
1001	      bestBond->setEndAtom(bestBond->getBeginAtom());
1002	      bestBond->setBeginAtom(atomAndBondVecs[bestBondEnd].first);
1003	    }
1004	    bestBond->setBondDir(bestBondDir);
1005	
1006	    auto newWedgeInfo = std::unique_ptr<RDKit::Chirality::WedgeInfoBase>(
1007	        new RDKit::Chirality::WedgeInfoAtropisomer(bond->getIdx(),
1008	                                                   bestBondDir));
1009	    wedgeBonds[bestBond->getIdx()] = std::move(newWedgeInfo);
1010	
1011	  } else {
1012	    BOOST_LOG(rdWarningLog)
1013	        << "Failed to find a good bond to set as UP or DOWN for an atropisomer - atoms are: "
1014	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
1015	    return false;
1016	  }
1017	
1018	  return true;
1019	}
