static int run(const char* label, std::unique_ptr<RDKit::RWMol> mol){
  if(!mol){ std::cout<<label<<": LOAD FAILED\n"; return 1; }
  RDKit::MolStandardize::TautomerEnumerator en;
  en.setRemoveBondStereo(false);
