    "OC(=O)/C=C/c1ccccc1",      // simple E alkene acid
    "C/C(O)=N/C",               // E imine (tautomer of hydroxylamine-ish)
    "CC(=O)N1CCc2ccccc21",      // amide with ring, no chiral
    "O=C(NC=C)C",               // amide
    "C1=C(N2CCCC2)C=C(S1)C(C3=CC=CC=C3)=O", // an atropisomer (biaryl)
